const output = [];

for (const item of $input.all()) {
  const json = item.json;

  // Skip empty/undefined items that sometimes appear from pagination boundaries
  if (!json || !json.name) continue;

  const name = json.name;

  // 1. Categorize based on the Canvas naming conventions
  let category = 'assignment';
  if (/-Lab/.test(name)) {
    category = 'lab';
  } else if (name.startsWith('KC -')) {
    category = 'knowledge_check';
  }

  // 2. Check submission status
  // Canvas returns null if not submitted. If the submission object is missing entirely, treat as unsubmitted.
  const is_submitted = json.submission?.submitted_at != null;

  // Add the new fields and pass the original Canvas data through
  output.push({
    json: {
      ...json,
      category,
      is_submitted
    }
  });
}

return output;

const items = $input.all().map(item => item.json);
const now = new Date();
const sevenDaysFromNow = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

const unsubmitted = [];
const dueSoon = [];

// 1. Filter the items
for (const item of items) {
  if (item.due_at) {
    const dueDate = new Date(item.due_at);
    if (dueDate >= now && dueDate <= sevenDaysFromNow) {
      dueSoon.push(item);
    }
  }

  if (!item.is_submitted) {
    const isExamPrep = item.name.includes('Exam Prep');
    if (!(item.category === 'knowledge_check' && isExamPrep)) {
      unsubmitted.push(item);
    }
  }
}

// 2. Group Unsubmitted items by Domain/Module
const groups = {
  'Linux': { regex: /\[LX\]/, items: [] },
  'Networking': { regex: /\[NF\]/, items: [] },
  'Security': { regex: /\[SF\]/, items: [] },
  'Python': { regex: /\[PF\]/, items: [] },
  'Databases': { regex: /\[DF\]/, items: [] },
  'AWS Core': { regex: /\[JAWS\]/, items: [] },
  'Knowledge Checks': { regex: /^KC -/, items: [] },
  'Other': { regex: /.*/, items: [] } 
};

for (const item of unsubmitted) {
  let matched = false;
  for (const [key, group] of Object.entries(groups)) {
    if (key === 'Other') continue;
    if (group.regex.test(item.name)) {
      group.items.push(item);
      matched = true;
      break;
    }
  }
  if (!matched) {
    groups['Other'].items.push(item);
  }
}

// 3. Build the Block Kit arrays
const blocks = [
  {
    "type": "header",
    "text": {
      "type": "plain_text",
      "text": "ðŸ—“ï¸ Daily Canvas Digest",
      "emoji": true
    }
  }
];

// Add the grouped unsubmitted sections
let hasUnsubmitted = false;
for (const [groupName, group] of Object.entries(groups)) {
  if (group.items.length === 0) continue;

  hasUnsubmitted = true;

  // Sort items alphabetically within the group
  group.items.sort((a, b) => a.name.localeCompare(b.name));

  const cappedList = group.items.slice(0, 10);
  let groupText = cappedList.map(i => `â€¢ ${i.name}`).join('\n');

  if (group.items.length > 10) {
    groupText += `\n_...and ${group.items.length - 10} more_`;
  }

  blocks.push({
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": `*${groupName}* (${group.items.length} pending)\n${groupText}`
    }
  });
  blocks.push({ "type": "divider" });
}

if (!hasUnsubmitted) {
  blocks.push({
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": "_Nothing pending here! ðŸŽ‰_"
    }
  });
  blocks.push({ "type": "divider" });
}

// 4. Add the Due Soon section
let dueSoonText = '';
if (dueSoon.length === 0) {
  dueSoonText = '_Nothing due in the next 7 days._';
} else {
  dueSoon.sort((a, b) => new Date(a.due_at) - new Date(b.due_at));
  dueSoonText = dueSoon.map(i => {
    const dateStr = new Date(i.due_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    return `â€¢ *${dateStr}* - ${i.name}`;
  }).join('\n');
}

blocks.push({
  "type": "header",
  "text": {
    "type": "plain_text",
    "text": "â³ Due in the next 7 days",
    "emoji": true
  }
});

blocks.push({
  "type": "section",
  "text": {
    "type": "mrkdwn",
    "text": dueSoonText
  }
});

return [{
  json: {
    blocks: blocks,
    unsubmitted_total: unsubmitted.length,
    due_soon_total: dueSoon.length
  }
}];
